function slidesFromBody(body) {
    const text = lyricsToPlainText(body);
    const blocks = text
        .split(/\n\s*\n+/)
        .map(value => value.trim())
        .filter(Boolean);
    return blocks.map(value => {
        let isChorus = false;
        const cleanText = value
            .replace(
                /(^|\n)[\t ]*priegiesmis(?:[\t ]*:[\t ]*|[\t ]*(?=\n|$))/giu,
                (_, lineStart) => {
                    isChorus = true;
                    return lineStart;
                },
            )
            .trim();
        return {
            text: cleanText,
            isChorus,
            chorusAfter: false,
        };
    });
}

